    "content": "import type { Metadata } from \"next\";\nimport { ScoreSummaryWorkspace } from \"@/components/score-workspaces\";\nimport { SiteFooter } from \"@/components/site-footer\";\nimport { SiteHeader } from \"@/components/site-header\";\nimport { getMemberSession } from \"@/lib/member-auth\";\n\nexport const metadata: Metadata = { title: \"個人積分摘要｜全國國中升學資訊網\", alternates: { canonical: \"/tools/summary\" }, robots: { index: false, follow: false } };\nexport default async function ScoreSummaryPage() { return <main className=\"min-h-screen jshs-page-shell\"><SiteHeader activeHref=\"/tools\" /><ScoreSummaryWorkspace isMember={Boolean(await getMemberSession())} /><SiteFooter /></main>; }\n"
